     <section class="card" aria-labelledby="page-title">
       <p class="eyebrow">Support</p>
       <h1 id="page-title">Contact our team</h1>
       <p class="lead">Send us a note and we’ll get back to you as soon as we can. Required fields are marked with an asterisk.</p>

       <form id="support-form" novalidate>
         <div class="form-field">
           <label for="full-name">Full name <span class="required" aria-hidden="true">*</span></label>
           <input
             id="full-name"
             name="fullName"
             type="text"
             autocomplete="name"
             required
             aria-describedby="full-name-error"
           >
           <p class="error" id="full-name-error" aria-live="polite"></p>
         </div>

         <div class="form-field">
           <label for="email">Email address <span class="required" aria-hidden="true">*</span></label>
           <input
             id="email"
             name="email"
             type="email"
             autocomplete="email"
             inputmode="email"
             required
             aria-describedby="email-error"
           >
           <p class="error" id="email-error" aria-live="polite"></p>
         </div>

         <div class="form-field">
           <label for="phone">Phone number</label>
           <input
             id="phone"
             name="phone"
             type="tel"
             autocomplete="tel"
             inputmode="tel"
             aria-describedby="phone-help phone-error"
             placeholder="(555) 123-4567"
           >
           <p class="helper" id="phone-help">Optional. Use a format like (555) 123-4567 or 555-123-4567.</p>
           <p class="error" id="phone-error" aria-live="polite"></p>
         </div>

         <div class="actions">
           <button type="submit">Send message</button>
         </div>

         <p class="status" id="form-status" aria-live="polite"></p>
       </form>
     </section>
   </main>

   <script>
     const form = document.getElementById('support-form');
     const fullName = document.getElementById('full-name');
     const email = document.getElementById('email');
     const phone = document.getElementById('phone');
     const status = document.getElementById('form-status');

     const fields = [
       {
         input: fullName,
         error: document.getElementById('full-name-error'),
         validate: value => value.trim() ? '' : 'Please enter your full name.'
       },
       {
         input: email,
         error: document.getElementById('email-error'),
         validate: value => {
           if (!value.trim()) return 'Please enter your email address.';
           return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value.trim())
             ? ''
             : 'Please enter a valid email address.';
         }
       },
       {
         input: phone,
         error: document.getElementById('phone-error'),
         validate: value => {
           if (!value.trim()) return '';
           return /^[+]?[\d\s().-]{7,}$/.test(value.trim())
             ? ''
             : 'Please use a valid phone number format.';
         }
       }
     ];

     function updateFieldState(field) {
       const message = field.validate(field.input.value);
       field.error.textContent = message;
       field.input.setAttribute('aria-invalid', message ? 'true' : 'false');
       return !message;
     }

     function validateForm() {
       let firstInvalid = null;
       const isValid = fields.reduce((allValid, field) => {
         const fieldValid = updateFieldState(field);
         if (!fieldValid && !firstInvalid) firstInvalid = field.input;
         return allValid && fieldValid;
       }, true);

       if (!isValid && firstInvalid) {
         firstInvalid.focus();
       }

       return isValid;
     }

     fields.forEach(field => {
       field.input.addEventListener('input', () => {
         updateFieldState(field);
         status.textContent = '';
       });

       field.input.addEventListener('blur', () => {
         updateFieldState(field);
       });
     });

     form.addEventListener('submit', event => {
       event.preventDefault();

       if (!validateForm()) {
         status.textContent = 'Please fix the highlighted fields and try again.';
         return;
       }

       status.textContent = 'Thanks! Your message is ready to send.';
       form.reset();
       fields.forEach(field => {
         field.error.textContent = '';
         field.input.removeAttribute('aria-invalid');
       });
     });
   </script>
 </body>
 </html>

